import sys, struct, os; sys.path.insert(0,'/tmp/kit')
from elfkit import *
# run on a real ELF to enumerate all classes
src = '/bin/ls'
d = open(src,'rb').read()
h = run(d, name='real.bin')
print("code", run.code, run.err.strip()[:200])
if h:
    cls = {}
    for o,k,c in open_close_events(h):
        if k=='+': cls[c] = cls.get(c,0)+1
    nonf = {c:n for c,n in cls.items() if c not in FIELDS}
    import re
    generic = {}
    for c,n in nonf.items():
        g = re.sub(r'\d+','N',c)
        generic[g] = generic.get(g,0)+n
    print("generic classes:", generic)
    print("field classes:", sorted(c for c in cls if c in FIELDS))
EOF
